Let $c>0$ and $\mu \in \mathcal{P}(\mathbb{R})$. A random probability measure is said to be a \emph{Dirichlet Process} with concentration $c$ and base distribution $\mu$, denoted $P \sim \mathsf{DP}(c \, \mu)$ if for every Borel partition $E_1,\dots,E_m$ of $\mathbb{R}$ we have 
\begin{align}
    (P(E_1),\dots,P(E_m)) \sim \mathsf{Dir}( c\mu(E_1), \dots, c \mu(E_m)) \, . 
\end{align}
If furthermore $\mu \in \mathcal{P}_{\mathrm{log}}(\mathbb{R})$, $\int |x| P(\mathrm{d}x) < \infty$ almost surely and the \emph{Dirichlet mean} of $P$ is defined as the random variable $Y_\mu = \int x P(\mathrm{d}x)$. We call its law the \emph{Markov-Krein Transform} (of order $c$) of the measure $\mu$ which we denote by 
\begin{align}
    \mathcal{M}_c \mu := \mathsf{Law}(Y_\mu) , \quad Y_\mu  = \int x P(\mathrm{d}x), \quad P \sim \mathsf{DP}(c \, \mu).
\end{align}

\label{prop:MKR_and_property_MKT} 
For $\mu \in  \mathcal{P}_{\mathrm{log}}(\mathbb{R})$ and any $z \in \mathbb{C}_+$ we have 
\begin{align}
\label{eq:MK_relation}
    \int (z - y)^{-c} \mathcal{M}_c\mu(\mathrm{d}y) = \mathrm{exp} \bigg\{ -c \int \log ( z - x) \mu(\mathrm{d}x) \bigg\},
\end{align}
and the transform $\mathcal{M}_c$ is injective on $\mathcal{P}_{\mathrm{log}}(\mathbb{R})$.

\label{thm:main_theorem}
For any $c>0$, the following assertions hold:
\begin{enumerate}
    \item[(i)] For any $\mu, \nu \in \mathcal{P}_{\mathrm{log}}(\mathbb{R})$, there exists a unique probability measure $\mu \oplus_c \nu \in \mathcal{P}_{\mathrm{log}}(\mathbb{R})$ such that 
     \begin{align}
         \mathcal{M}_c( \mu \oplus_c \nu) = (\mathcal{M}_c \mu) \ast (\mathcal{M}_c \nu);
     \end{align}
     \item[(ii)] For any $\mu, \nu \in \mathcal{P}_{\mathrm{log}}(\mathbb{R}_+)$, there exists a unique probability measure $\mu \otimes_c \nu \in \mathcal{P}_{\mathrm{log}}(\mathbb{R}_+)$ such that 
     \begin{align}
         \mathcal{M}_c( \mu \otimes_c \nu) = (\mathcal{M}_c \mu) \circledast (\mathcal{M}_c \nu).
     \end{align} 
\end{enumerate}

For $\alpha<1$, we let 
\begin{align}
    \mathcal{S}_\alpha := \bigg\{ f \in \mathcal{H}_1(\mathbb{D}): \frac{f(z)}{z} \neq 0 \mbox{ on } \mathbb{D}, \;  \mathfrak{R} \frac{z f'(z)}{f(z)} > \alpha  \mbox{ on } \mathbb{D} \bigg\} .  
\end{align}
Note that the functions $\frac{f}{z} , \mathfrak{R} \frac{z f'}{f}$ are assigned their removal value $1$ at the origin. We define the \emph{class of prestarlike functions of order $\alpha$} has 
\begin{align}
    \mathcal{R}_\alpha := \bigg\{ f \in \mathcal{H}_1(\mathbb{D}) : \Delta^{2(1-\alpha)} f \in \mathcal{S}_\alpha \bigg\}. 
\end{align}
For $\gamma \in \mathbb{C}\setminus \{0\}$ and $t \in [0,1]$ let
\begin{align}
    \omega_{\gamma,t}(z) = \frac{\gamma z}{1 -tz }, \quad z \in \mathbb{D}.
\end{align}
For $| \gamma + t| <1$, $   \omega_{\gamma,t} (\mathbb{D}) \subseteq \mathbb{\Lambda}$ and the \emph{class of universally prestarlike functions of order $\alpha$} is defined as
\begin{align}
    \mathcal{R}^{(\mathrm{u})}_{\alpha} :=\{ f \in \mathcal{H}_1(\mathbb{\Lambda}) : \gamma^{-1} f \circ \omega_{\gamma,t} \in \mathcal{R}_\alpha \mbox{ for every } t \in [0,1], \gamma \neq 0, |\gamma +t| \le 1\}. 
\end{align}

\label{thm:prestartlike_stieltjes} Let $\alpha<1$, the following hold: 
\begin{enumerate}
    \item[(i)] for $f \in \mathcal{H}_1(\mathbb{\Lambda})$, we have  $ f \in \mathcal{R}^{(\mathsf{u})}_\alpha \Leftrightarrow \frac{\Delta^{3-2\alpha} f}{\Delta^{2(1-\alpha)}f} \in \mathcal{T}$;
    \item[(ii)] if $f,g \in \mathcal{R}^{(\mathsf{u})}_\alpha$ then $f \odot g$ has a holomorphic continuation to  $\mathbb{\Lambda}$ and  $f \odot g \in \mathcal{R}^{(\mathsf{u})}_\alpha$. 
\end{enumerate}

Let $c>0$.
\label{lem:support_MK}
\begin{enumerate}
    \item[(i)] If $\mu \in \mathcal{P}_{\mathrm{c}}(\mathbb{R})$ then $\mu$ and $\mathcal{M}_c \mu$ have the same smallest closed interval containing their respective supports. 
    \item[(ii)] If $\mu_n \Rightarrow \mu$ with $\mu_n \in \mathcal{P}_{\mathrm{c}}(\mathbb{R})$ supported in the same compact interval then $\mathcal{M}_c \mu_n \Rightarrow \mathcal{M}_c \mu$.
\end{enumerate}

Let $c>0$ and $\tau \in \mathcal{P}(\mathbb{R})$, we introduce the standard and generalized Stieltjes transform of order $c>0$ of $\tau$ as
\begin{align}
\label{eq:definition_stietljes}
    g_{\tau}(z) := \int_{\mathbb{R}} \frac{1}{z-x} \tau(\mathrm{d}x) ,  
    \qquad 
    G^{(c)}_\tau(z) := \int_{\mathbb{R}} (z-x)^{-c} \tau(\mathrm{d}x) , \qquad z \in \mathbb{C}_+. 
\end{align}
Weak convergence of the sequence $\eta_n$ gives that $g_{n} := g_{\eta_n} \to g_{\eta}$ and $  G^{(c)}_n :=   G^{(c)}_{\eta_n} \to   G^{(c)}_\eta$ locally uniformly on $\mathbb{C}_+$ and for every $\tau \in \mathcal{P}(\mathbb{R})$ we have 
\begin{align}
\label{eq:limit_gen_stietjes_inf}
    (\mathrm{i}y)^c G^{(c)}_\tau(\mathrm{i}y)  \to 1, \qquad ( \mathrm{i} y)^{c+1} {(G^{(c)}_\tau)}^\prime ( \mathrm{i} y)  \to -c, \qquad \mbox{ as } y\to\infty,
\end{align}
hence $G^{(c)}_\tau$ is not identically zero. Form the Markov-Krein relation of Prop.~\ref{prop:MKR_and_property_MKT} and Hurwitz theorem \cite[Chapter VIII,Section 3]{gamelin2001complex} $G^{(c)}_\eta(z) \neq 0$ for all $z \in \mathbb{C}_+$ and differentiating the Markov-Krein relation \eqref{eq:MK_relation} and taking the limit $n \to \infty$ gives
\begin{align}
\label{eq:convergence_D_MKR}
    g_{\rho_n} = -\frac{1}{c} \frac{ (G^{(c)}_{\eta_n})^\prime  }{G^{(c)}_{\eta_n}} 
    &\to
    g = 
    -\frac{1}{c} \frac{ (G^{(c)}_{\eta})^\prime  }{G^{(c)}_{\eta}},
\end{align}
locally uniformly on $\mathbb{C}_+$ and Eq.~\eqref{eq:limit_gen_stietjes_inf} gives the asymptotic $\mathrm{i}y g(\mathrm{i}y) \to 1$ as $y \to \infty$. By Stieltjes continuity theorem \cite{geronimo2003necessary}, there is a probability measure $\rho$ such that $g = g_\rho$ and $\rho_n \Rightarrow \rho$. 
We check that $\rho$ has finite logarithmic moment. Form the righthand side of Eq.~\eqref{eq:convergence_D_MKR}  we have for $r>0$:
\begin{align}
    \frac{\mathrm{d}}{\mathrm{d}r}\log  |G^{(c)}_\eta (\mathrm{i}r)| = - c \int_{\mathbb{R}} \frac{r}{x^2 +r^2} \rho(\mathrm{d}x), 
\end{align}
which by integrating from $r=1$ to $r=R>1$ and adding $\log R^c =c \log R$ to both sides gives
\begin{align}
    \log  R^c |G^{(c)}_\eta (\mathrm{i}R)| -\log  |G^{(c)}_\eta (\mathrm{i})| = \frac{c}{2} \int_{\mathbb{R}} \log \bigg( \frac{1+x^2}{1+\frac{x^2}{R^2}} \bigg)\rho(\mathrm{d}x)
    \le \frac{c}{2} \int_{\mathbb{R}} \log (1+x^2)\rho(\mathrm{d}x).
\end{align}
Now by Eq.~\eqref{eq:limit_gen_stietjes_inf}, $\log  R^c |G^{(c)}_\eta (\mathrm{i}R)|\to 0$ as $R\to \infty$ and since  $0 \le \log \bigg( \frac{1+x^2}{1+\frac{x^2}{R^2}} \bigg) \le \log (1+x^2)$ with equality as $R\to\infty$, we obtain by monotone convergence
\begin{align}
    \int_{\mathbb{R}} \log (1+x^2)\rho(\mathrm{d}x) \le -\frac{2}{c} \log  |G^{(c)}_\eta (\mathrm{i})| < \infty . 
\end{align}
Since $\log(1+|x|) \le \log(1+x^2) +\frac{1}{2} \log 2$, we have $\rho \in \mathcal{P}_\mathrm{log}(\mathbb{R})$.  The logarithmic-derivative characterization \cite[Lemma IV.7]{nakano2025classical} gives $\eta = \mathcal{M}_c \rho$. Uniqueness follows from injectivity of $\mathcal{M}_c$.

\label{prop:Multiplicative_conv_compact_support}
For $c>0$ and $\mu, 
u \in \mathcal{P}_{\mathrm{c}}(\mathbb{R}_+)$  there exists a unique probability measure $ho \in \mathcal{P}_{\mathrm{c}}(\mathbb{R}_+)$ such that $\mathcal{M}_c ho = (\mathcal{M}_c \mu) \circledast (\mathcal{M}_c 
u)$. Furthermore if $\mathrm{Supp} \mu \subseteq [0,a]$ and $\mathrm{Supp} 
u \subseteq [0,b]$, then $\mathrm{Supp} ho \subseteq [0, ab]$.

By Lemma~\ref{lem:affine_shift} it suffices to prove the result for $\mu,\nu \in \mathcal{P}([0,1])$ since for $a,b>0$ we can always apply the linear push forward maps $x\mapsto x/a$ and  $x\mapsto x/b$  and then dilate the output distribution by $x \mapsto ab \, x$. If $a=0$ and/or $b=0$, one input is zero and so is the output.  Let $Y_\mu$, $Y_\nu$ (independent) be their associated Dirichlet means of order $c$, taking values in $[0,1]$ by Lemma~\ref{lem:support_MK}. We define 
\begin{align}
\label{eq:expression_gen_stieltjes}
    G^{(c)}_\mu(z)  := \mathbb{E}_{Y_\mu} \Big[ ( 1 - zY_\mu)^{-c} \Big] = \mathrm{exp} \Big\{- c \int_{[0,1]} \log (1 - zx) \mu(\mathrm{d}x) \Big\} \, , \qquad z \in \mathbb{\Lambda},
\end{align}
where the second equality follows from the Markov-Krein relation \eqref{eq:MK_relation}. Similarly let
\begin{align}
    H_\mu(z) := z  \mathbb{E}_{Y_\mu} \Big[ ( 1 - zY_\mu)^{-1} \Big], \qquad   z \in \mathbb{\Lambda}. 
\end{align}
 These functions are holomorphic on $\mathbb{\Lambda}$ with ${H}^{\prime}_{\mu}(z) = \mathbb{E}_{Y_\mu} \Big[ ( 1 - zY_\mu)^{-2} \Big]$, thus $H_\mu(0)=0$ and ${H}^{\prime}_{\mu}(0)=1$ that is $H_\mu \in \mathcal{H}_1(\mathbb{\Lambda})$. The binomial series \eqref{eq:binomial_series} gives that these two functions are linked by 
 \begin{align}
     \Delta^{c} H_\mu =  z G^{(c)}_\mu(z), 
 \end{align}
 such that, thanks to Eq.~\eqref{eq:quotient_simplication}, we can express the quotient as 
 \begin{align}
     \frac{\Delta^{c+1} H_\mu}{\Delta^{c} H_\mu} 
     &= 
      1 + \frac{1}{c}  \frac{ z (G^{(c)}_\mu)'(z)}{ G^{(c)}_\mu(z)} ,
 \end{align}
 and by differentiating the right-hand-side of Eq.~\eqref{eq:expression_gen_stieltjes} we obtain 
 \begin{align}
      \frac{\Delta^{c+1} H_\mu}{\Delta^{c} H_\mu} 
     &= \int_{[0,1]} \frac{1}{1-zx} \mu(\mathrm{d}x) \in \mathcal{T}
 \end{align}
by Eq.~\eqref{eq:def_Stieltjes_class}. Thus, Part-(i) of Thm.~\ref{thm:prestartlike_stieltjes} implies that for all $\mu \in \mathcal{P}([0,1])$, $H_\mu \in \mathcal{R}^{(\mathrm{u})}_{1-c/2}$. 

    Next, let  $Y = Y_\mu Y_\nu$ taking values in $[0,1]$ and define 
    \begin{align}
    \label{eq:def_Htilde}
        {\tilde{H}}_{Y}(z) 
        &=
        z \mathbb{E}_{Y}[ (1 -z Y)^{-1} ] \qquad z \in \mathbb{\Lambda}, 
    \end{align}
which is again holomorphic on $\mathbb{\Lambda}$. By independence of $Y_\mu, Y_\nu$ we have 
\begin{align}
     {\tilde{H}}_{Y}(z) 
        &=
         z \sum_{n\ge 0} \mathbb{E}[Y^n] z^n = z \sum_{n\ge 0} \mathbb{E}[Y_\mu^n] \mathbb{E}[Y_\nu^n] z^n =  (H_\mu \odot H_\nu)(z) &\qquad z \in \mathbb{D}. 
\end{align}
The series equality hold on $\mathbb{D}$ and is continued on $\mathbb{\Lambda}$ by Eq.~\eqref{eq:def_Htilde}.  
Hence by Part-(ii) of Thm.~\ref{thm:prestartlike_stieltjes}, $ \tilde{H}_{Y} \in \mathcal{R}^{(\mathrm{u})}_{1-c/2}$. We can now apply the direct implication of Part-(i) of Thm.~\ref{thm:prestartlike_stieltjes} to $  {\tilde{H}}_{Y}$: there exists $\rho \in \mathcal{P}([0,1])$ such that 
\begin{align}
      \frac{\Delta^{c+1} {\tilde{H}}_{Y}}{\Delta^{c}  {\tilde{H}}_{Y}} 
     &= \int_{[0,1]} \frac{1}{1-zx} \rho(\mathrm{d}x) .
 \end{align}
Define  on $\mathbb{\Lambda}$, $\tilde{G}^{(c)}_Y(z) := \mathbb{E}[ (1-zY)^{-c}]$. The same previous computation gives
 \begin{align}
     \frac{(\tilde{G}^{(c)}_Y)^{\prime}(z)}{\tilde{G}^{(c)}_Y(z)} = c \int_{[0,1]} \frac{x}{1-zx} \rho(\mathrm{d}x), 
 \end{align}
 since $\tilde{G}^{(c)}_Y(0)=1$ we get by integration and the use of the Markov-Krein relation  Eq.~\eqref{eq:MK_relation} (first in a neighborhood of the origin and then by continuation on $\mathbb{\Lambda})$: 
 \begin{align}
     \tilde{G}^{(c)}_Y(z) 
     &= \mathrm{exp} \bigg\{ -c \int_{[0,1]} \log (1 - zx) \rho(\mathrm{d}x) \bigg\}= \mathbb{E}[(1 - zY_\rho)^{-c}] =: G_\rho^{(c)}(z), \quad z \in \mathbb{\Lambda}. 
 \end{align}
Equality of the Taylor coefficients gives
\begin{align}
\mathbb{E}[Y^n] = \mathbb{E}[Y_\rho^n], \quad n \in \mathbb{N},
\end{align}
and since the two distributions are compactly supported, they are determined by their moments, that is $\mathsf{Law}(Y) =  \mathcal{M}_c \rho$ and injectivity of $\mathcal{M}_c$ gives uniqueness and  concludes the proof.

Let $\epsilon>0$, and consider the affine maps $A_\epsilon : x \mapsto 1 + \epsilon x$ and $A^{-1}_\epsilon : x \mapsto (x-1)/\epsilon$. Let  $\epsilon_0 = 1/(1+\max(0,-a_-,-b_-))$, then for $\epsilon \in (0,\epsilon_0)$ we have ${(A_\epsilon)}_\# \mu ,{(A_\epsilon)}_\# \nu \in \mathcal{P}_{\mathrm{c}}(\mathbb{R}_+)$. From Prop.~\ref{prop:Multiplicative_conv_compact_support}, there exists $\rho_\epsilon \in \mathcal{P}_{\mathrm{c}}(\mathbb{R}_+)$ such that 
    \begin{align}
    \label{eq:rho_epsilon}
        \mathcal{M}_c(\rho_\epsilon)
        &=
       \mathcal{M}_c( {(A_\epsilon)}_\# \mu) \circledast  \mathcal{M}_c( {(A_\epsilon)}_\# \nu).
    \end{align}
    For $\epsilon \in (0,\epsilon_0)$, the positive random variable $(1+\epsilon Y_\mu)(1+\epsilon Y_\nu)$ takes values in 
    \begin{align}
        I_{\epsilon} := [(1 + \epsilon a_-)( 1+ \epsilon b_-) , (1 + \epsilon a_+)( 1+ \epsilon b_+)  ] \subseteq \mathbb{R}_+,
    \end{align}
    and by Part-(i) of Lemma \ref{lem:support_MK}, we also have $\mathrm{Supp} \rho_\epsilon \subseteq  I_{\epsilon} $. 

    Next define $\varrho_\epsilon := (A^{-1}_\epsilon)_\# \rho_\epsilon$. By applying $A^{-1}_\epsilon$ to Eq.~\eqref{eq:rho_epsilon} and since the Markov Krein transform commutes with affine maps (Lemma~\ref{lem:affine_shift}) we have
    \begin{align}
    \label{eq:MKR_epsilon}
         \mathcal{M}_c \varrho_\epsilon  
        &=  \mathsf{Law}\Big( \epsilon^{-1}(  (1+\epsilon Y_\mu)(1+\epsilon Y_\nu) -1)\Big) 
        = \mathsf{Law}( Y_\mu + Y_\nu + \epsilon Y_\mu Y_\nu). 
    \end{align}
    Furthermore, 
    \begin{align}
    \label{eq:bound_support_eps}
        \mathrm{Supp} \varrho_\epsilon \subseteq J_\epsilon := A^{-1}_\epsilon I_\epsilon = [ a_- + b_- + \epsilon a_-b_- , a_+ + b_+ + \epsilon a_+ b_+]. 
    \end{align}
    For $\epsilon \in (0,\epsilon_0)$, there exists a $K>0$ such that $J_\epsilon \subseteq [-K,K]$ and therefore the family $(\varrho_{\epsilon})_\epsilon$ is tight. By Prokhorov's theorem \cite[Section 5]{billingsley1999convergence}, starting with a sequence $\epsilon_n \downarrow 0$, there exists a subsequence, still denoted $(\epsilon_n)_n$ such that $\varrho_{\epsilon_n} \Rightarrow \varrho \in \mathcal{P}([-K,K])$. By Part (ii) of Lemma~\ref{lem:support_MK} and  the limit $\epsilon \downarrow 0$  of Eq.~\eqref{eq:MKR_epsilon}, we have  $\mathcal{M}_c \varrho_{\epsilon_n} \Rightarrow \mathsf{Law}( Y_\mu + Y_\nu) = \mathcal{M}_c \mu \ast \mathcal{M}_c \nu$ with the associated bound for the support following from Eq.~\eqref{eq:bound_support_eps}. Injectivity of $\mathcal{M}_c$ gives again uniqueness and implies that any subsequential limit of $(\varrho_\epsilon)_\epsilon$ converges to $\varrho$ which concludes the proof.
